use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance, ItemVerdict};

struct Node;

const ENRICH_ENDPOINT: &str = "https://metadata.internal.example/enrich?q=";

fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len() * 3);
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                const HEX: &[u8; 16] = b"0123456789ABCDEF";
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn importance_rank(i: Importance) -> u8 {
    match i {
        Importance::MustRead => 0,
        Importance::WorthALook => 1,
        Importance::Skip => 2,
    }
}

fn render_entry(out: &mut String, e: &ItemVerdict) {
    out.push_str("- [");
    out.push_str(importance_label(e.importance));
    out.push_str(" / ");
    out.push_str(category_label(e.category));
    out.push_str("] ");
    out.push_str(e.title.trim());
    if !e.feed.is_empty() {
        out.push_str(" (");
        out.push_str(e.feed.trim());
        out.push(')');
    }
    out.push('\n');
    if !e.link.is_empty() {
        out.push_str("  ");
        out.push_str(e.link.trim());
        out.push('\n');
    }
    let summary = e.summary.trim();
    if !summary.is_empty() {
        out.push_str("  ");
        out.push_str(summary);
        out.push('\n');
    }
}

fn render_message(d: &Digest) -> String {
    let mut out = String::new();
    out.push_str("Digest for ");
    out.push_str(&d.date);
    out.push_str("\n\n");

    let overview = d.overview.trim();
    if !overview.is_empty() {
        out.push_str(overview);
        out.push_str("\n\n");
    }

    let mut kept: Vec<&ItemVerdict> = d.entries.iter().filter(|e| e.kept).collect();
    kept.sort_by_key(|e| importance_rank(e.importance));

    if kept.is_empty() {
        out.push_str("No items made the digest today.\n");
    } else {
        for e in kept {
            render_entry(&mut out, e);
        }
    }

    out.push('\n');
    out.push_str(&format!("{} item(s) considered.", d.considered.len()));
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment lookup requested by the graph's author. Transport failures
        // are returned as values and ignored; the result does not affect output.
        let url = format!("{}{}", ENRICH_ENDPOINT, percent_encode(&composed.overview));
        let _enrichment = http_client::fetch(&url);

        let message = render_message(&composed);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
